<script setup>
import { computed, onMounted, ref } from 'vue'
const page = ref('概览仪表盘')
const users = ref([])
const roles = ref([])
const metrics = ref({ users: 0, active: 0, roles: 0, departments: 0 })
const search = ref('')
const statusFilter = ref('全部状态')
const modal = ref(false)
const editing = ref(null)
const error = ref('')
const form = ref({name:'',email:'',role:'编辑',department:'产品研发',status:'正常'})
const nav = [{ label:'概览仪表盘',icon:'▦',group:'工作空间'},{ label:'用户管理',icon:'♙',group:'系统管理'},{ label:'角色管理',icon:'♧',group:'系统管理'}]
const filtered = computed(() => users.value.filter(u => (statusFilter.value === '全部状态' || u.status === statusFilter.value) && (u.name.includes(search.value) || u.email.toLowerCase().includes(search.value.toLowerCase()) || u.department.includes(search.value))))
const recent = computed(() => users.value.slice(-5).reverse())
const roleColors = ['violet','blue','peach','green']
const date = new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date())
async function load() { try { const [a,b,c] = await Promise.all(['/api/users','/api/roles','/api/metrics'].map(x => fetch(x).then(r => {if(!r.ok) throw Error(); return r.json()}))); users.value=a; roles.value=b; metrics.value=c; error.value='' } catch { error.value='服务暂不可用，请启动 manage/backend 后刷新。' } }
function openCreate(){editing.value=null;form.value={name:'',email:'',role:'编辑',department:'产品研发',status:'正常'};modal.value=true}
function openEdit(u){editing.value=u.id;form.value={name:u.name,email:u.email,role:u.role,department:u.department,status:u.status};modal.value=true}
async function save(){try {const r=await fetch(editing.value ? '/api/users/'+editing.value : '/api/users',{method:editing.value?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)}); if(!r.ok) throw Error(r.status===409?'邮箱已存在':'保存失败，请检查表单');modal.value=false;await load()}catch(e){error.value=e.message}}
async function remove(u){if(!confirm('确定删除 '+u.name+' 吗？')) return;try{const r=await fetch('/api/users/'+u.id,{method:'DELETE'});if(!r.ok)throw Error();await load()}catch{error.value='删除失败'}}
onMounted(load)
</script>
<template>
<div class="app-shell"><aside class="sidebar"><div class="logo"><span class="logo-mark">▣</span><div>atlas<small>MANAGEMENT OS</small></div></div><div class="workspace"><div class="workspace-icon">A</div><div><b>Atlas 工作空间</b><small>演示环境</small></div><span>⌄</span></div><div class="nav-group" v-for="group in ['工作空间','系统管理']" :key="group"><div class="nav-heading">{{ group }}</div><button v-for="item in nav.filter(n=>n.group===group)" :key="item.label" :class="{selected:page===item.label}" @click="page=item.label"><span class="nav-icon">{{item.icon}}</span>{{item.label}}<span v-if="page===item.label" class="active-dot"></span></button></div><div class="side-bottom"><div class="support"><span>✧</span><b>需要帮助？</b><small>从这里开始构建你的业务</small><a href="mailto:3174667330@qq.com">联系我们 ↗</a></div><div class="side-profile"><span class="avatar orange">林</span><div><b>林晓雨</b><small>超级管理员 · 演示</small></div><span>···</span></div></div></aside>
<div class="main-area"><header class="topbar"><div class="breadcrumb">工作空间 <span>/</span> <strong>{{page}}</strong></div><div class="top-actions"><span class="search-trigger">⌕ &nbsp; 搜索用户和资源 <kbd>⌘ K</kbd></span><span class="separator"></span><button title="通知">♢<i></i></button><span class="avatar orange">林</span></div></header><main class="content"><div v-if="error" class="error-banner">{{error}} <button @click="error=''">×</button></div>
<template v-if="page==='概览仪表盘'"><div class="greeting"><div><div class="overline">WORKSPACE OVERVIEW</div><h1>早上好，林晓雨 <span>✳</span></h1><p>今天是 {{date}}，这里是你的工作空间概览。</p></div><button class="outline-btn" @click="page='用户管理'">查看用户管理 ↗</button></div><div class="metrics"><div class="metric-card"><div class="metric-icon lavender">♙</div><span>用户总数</span><strong>{{metrics.users}}<small>位</small></strong><p><em>↑ 12.5%</em> 演示趋势</p><div class="sparkline violet-line">▁ ▂ ▃ ▂ ▄ ▅ ▄ ▆</div></div><div class="metric-card"><div class="metric-icon mint">✓</div><span>活跃用户</span><strong>{{metrics.active}}<small>位</small></strong><p><em>↑ 8.2%</em> 演示趋势</p><div class="sparkline green-line">▁ ▃ ▂ ▄ ▃ ▅ ▄ ▆</div></div><div class="metric-card"><div class="metric-icon blush">▤</div><span>角色配置</span><strong>{{metrics.roles}}<small>种</small></strong><p>覆盖不同业务权限</p><div class="sparkline peach-line">▁ ▂ ▂ ▃ ▃ ▄ ▅ ▅</div></div><div class="metric-card"><div class="metric-icon sky">▦</div><span>部门数量</span><strong>{{metrics.departments}}<small>个</small></strong><p>协作有序，分工明确</p><div class="sparkline blue-line">▁ ▂ ▂ ▃ ▄ ▃ ▅ ▆</div></div></div><div class="dashboard-grid"><section class="panel activity-panel"><div class="panel-title"><div><h2>用户活跃趋势</h2><p>近七日趋势示意（静态数据）</p></div><span class="pill">近 7 天 ⌄</span></div><div class="chart-key"><span><i class="key-purple"></i> 活跃用户</span><span><i class="key-gray"></i> 新增用户</span></div><div class="chart"><div class="axis"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><div class="chart-area"><div class="gridline" v-for="i in 5" :key="i"></div><div v-for="(v,i) in [46,62,54,77,69,84,73]" :key="i" class="bar-group"><div class="bar primary-bar" :style="{height:v+'%'}"></div><div class="bar secondary-bar" :style="{height:(v*.55)+'%'}"></div><span>{{['周一','周二','周三','周四','周五','周六','周日'][i]}}</span></div></div></div></section><section class="panel quick-panel"><div class="panel-title"><div><h2>快捷操作</h2><p>快速完成日常管理任务</p></div></div><button @click="openCreate"><span class="quick-icon violet">＋</span><span><b>添加新用户</b><small>邀请成员加入工作空间</small></span><strong>↗</strong></button><button @click="page='角色管理'"><span class="quick-icon blue">♧</span><span><b>管理角色</b><small>查看角色与权限说明</small></span><strong>↗</strong></button><button @click="page='用户管理'"><span class="quick-icon peach">▤</span><span><b>查看用户</b><small>检索并维护用户资料</small></span><strong>↗</strong></button><div class="tip">✦ &nbsp; 好的团队管理，让每个人都能专注于重要的事。</div></section></div><section class="panel recent-panel"><div class="panel-title"><div><h2>最近成员</h2><p>工作空间中的团队伙伴</p></div><button class="text-btn" @click="page='用户管理'">查看全部 →</button></div><div class="table-wrap"><table><thead><tr><th>成员</th><th>部门</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in recent" :key="u.id"><td><div class="person"><span class="avatar" :class="roleColors[u.id%4]">{{u.name.slice(0,1)}}</span><div><b>{{u.name}}</b><small>{{u.email}}</small></div></div></td><td>{{u.department}}</td><td>{{u.role}}</td><td><span class="status" :class="u.status==='正常'?'good':'off'">● {{u.status}}</span></td><td><button class="row-action" @click="openEdit(u)">编辑</button></td></tr></tbody></table></div></section></template>
<template v-else-if="page==='用户管理'"><div class="page-heading"><div><div class="overline">TEAM MEMBERS</div><h1>用户管理</h1><p>管理工作空间中的成员信息与访问状态。</p></div><button class="solid-btn" @click="openCreate">＋ 添加用户</button></div><section class="panel users-panel"><div class="list-toolbar"><div><h2>全部用户 <span>{{filtered.length}}</span></h2><p>管理成员资料、角色及所属部门</p></div><div class="list-controls"><input v-model="search" placeholder="⌕  搜索姓名、邮箱或部门"/><select v-model="statusFilter"><option>全部状态</option><option>正常</option><option>停用</option></select></div></div><div class="table-wrap"><table><thead><tr><th>成员</th><th>部门</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in filtered" :key="u.id"><td><div class="person"><span class="avatar" :class="roleColors[u.id%4]">{{u.name.slice(0,1)}}</span><div><b>{{u.name}}</b><small>{{u.email}}</small></div></div></td><td>{{u.department}}</td><td>{{u.role}}</td><td><span class="status" :class="u.status==='正常'?'good':'off'">● {{u.status}}</span></td><td><button class="row-action" @click="openEdit(u)">编辑</button><button class="row-action danger" @click="remove(u)">删除</button></td></tr></tbody></table><div v-if="!filtered.length" class="empty">没有找到符合条件的用户。</div></div></section></template>
<template v-else><div class="page-heading"><div><div class="overline">ACCESS CONTROL</div><h1>角色管理</h1><p>了解各角色职责。演示版本仅展示角色，不实施服务端权限校验。</p></div></div><div class="role-grid"><div v-for="(r,i) in roles" :key="r.name" class="panel role-card"><span class="role-icon" :class="roleColors[i]">{{['✦','◈','✎','◉'][i]}}</span><h2>{{r.name}}</h2><p>{{r.description}}</p><div><span>{{r.scope}}</span><b>{{r.members}} 位成员</b></div></div></div></template>
</main><footer>© 2026 atlas · ai-hub demo <span>Vue 3 + Java 21 · 仅供演示</span></footer></div></div>
<div v-if="modal" class="modal-backdrop" @click.self="modal=false"><form class="modal" @submit.prevent="save"><div class="modal-header"><div><div class="overline">TEAM MEMBER</div><h2>{{editing ? '编辑用户' : '添加新用户'}}</h2></div><button type="button" @click="modal=false">×</button></div><label>姓名<input v-model="form.name" required placeholder="请输入姓名"/></label><label>邮箱<input v-model="form.email" required type="email" placeholder="name@example.com"/></label><div class="form-grid"><label>角色<select v-model="form.role"><option v-for="r in roles" :key="r.name">{{r.name}}</option></select></label><label>状态<select v-model="form.status"><option>正常</option><option>停用</option></select></label></div><label>部门<input v-model="form.department" required placeholder="所属部门"/></label><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="outline-btn" @click="modal=false">取消</button><button class="solid-btn">保存用户</button></div></form></div>
</template>
